'.sim-buyrunuz .b-row{display:flex;align-items:center;gap:10px;height:40px;border-bottom:1.5px dashed rgba(58,36,24,.2);font-size:13.5px;font-weight:700}',
'.sim-buyrunuz .b-row:last-child{border-bottom:0}',
'.sim-buyrunuz .b-row b{width:26px;height:26px;border-radius:50%;background:#3A2418;color:#FFF6E5;display:flex;align-items:center;justify-content:center;font-size:14px;flex:none}',
'.sim-buyrunuz .b-row.me b{background:#E63946}',
'.sim-buyrunuz .b-row span{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}',
'.sim-buyrunuz .b-row em{font-style:normal;font-weight:800;color:#8A5A3C;font-size:12px}',
'.sim-buyrunuz .b-row svg{width:34px;height:28px}',
'.sim-buyrunuz .b-fbtns{display:flex;gap:10px}',
'.sim-buyrunuz .b-fbtns .b-btn{flex:1}',
'.sim-buyrunuz .b-fbtns .b-btn.ghost{flex:0 0 108px}',
/* tap ring + toast */
'.sim-buyrunuz .b-tap{position:absolute;width:44px;height:44px;margin:-22px 0 0 -22px;border-radius:50%;border:3px solid #E63946;pointer-events:none;z-index:200;animation:simBzTap .6s ease-out forwards}',
'@keyframes simBzTap{0%{transform:scale(.4);opacity:1}100%{transform:scale(1.5);opacity:0}}',
'.sim-buyrunuz .b-toast{position:absolute;left:24px;right:24px;bottom:34px;z-index:210;background:#3A2418;color:#FFF6E5;font-size:13px;font-weight:800;padding:12px 14px;border-radius:16px;text-align:center;opacity:0;transform:translateY(14px);transition:opacity .3s,transform .3s;pointer-events:none}',
'.sim-buyrunuz .b-toast.show{opacity:1;transform:none}',
/* cover */
'.sim-buyrunuz.sim-buyrunuz-cover{position:absolute;inset:0;background:linear-gradient(180deg,#8ED4F2 0%,#D9EEF8 46%,#FFE8C2 56%,#3FB0D8 56%,#3FB0D8 62%,#7BC96F 62%)}',
'.sim-buyrunuz .b-cv-road{position:absolute;left:0;right:0;bottom:0;height:62px;background:linear-gradient(180deg,#5E5E66,#5E5E66);border-top:5px solid #FFF6E5;background-image:repeating-linear-gradient(90deg,#FFF6E5 0 22px,transparent 22px 44px);background-size:100% 4px;background-repeat:no-repeat;background-position:0 26px}',
'.sim-buyrunuz .b-cv-curb{position:absolute;left:0;right:0;bottom:62px;height:6px;background:repeating-linear-gradient(90deg,#E63946 0 18px,#FFF6E5 18px 36px)}',
'.sim-buyrunuz .b-cv-logo{position:absolute;top:22px;left:18px;font-size:44px;line-height:1;color:#FFF6E5;-webkit-text-stroke:1.5px #3A2418;text-shadow:4px 4px 0 #E63946;transform:rotate(-2deg)}',
'.sim-buyrunuz .b-cv-tag{position:absolute;top:72px;left:18px;background:#3A2418;color:#FFF6E5;font-size:12px;font-weight:800;padding:4px 10px;border-radius:10px}',
'.sim-buyrunuz .b-cv-kart{position:absolute;left:138px;bottom:20px;width:166px;height:84px}',
'.sim-buyrunuz .b-cv-kart svg{width:100%;height:100%;filter:drop-shadow(0 4px 0 rgba(58,36,24,.2))}',
'.sim-buyrunuz .b-cv-sun{position:absolute;top:14px;right:22px;width:34px;height:34px;border-radius:50%;background:#FFD166;box-shadow:0 0 0 8px rgba(255,209,102,.3)}',
'.sim-buyrunuz .b-cv-pos{position:absolute;right:18px;top:60px;background:#FFF6E5;border:2px solid #3A2418;border-radius:12px;padding:3px 9px;font-size:16px;color:#E63946;box-shadow:0 3px 0 #3A2418}',
'.sim-buyrunuz .b-cv-pos small{color:#3A2418;font-size:11px;font-weight:800}',
'.sim-buyrunuz .b-cv-cay{position:absolute;left:96px;bottom:74px;width:26px;height:36px}',
'.sim-buyrunuz .b-cv-cay svg{width:100%;height:100%;filter:drop-shadow(0 0 6px #FFD166) drop-shadow(0 0 2px #FFD166)}',
'.sim-buyrunuz .b-cv-cloud{position:absolute;top:26px;left:206px;width:58px;height:18px;border-radius:9px;background:rgba(255,255,255,.9)}',
'.sim-buyrunuz .b-cv-cloud:before,.sim-buyrunuz .b-cv-cloud:after{content:"";position:absolute;bottom:5px;border-radius:50%;background:inherit}',
'.sim-buyrunuz .b-cv-cloud:before{left:10px;width:24px;height:24px}.sim-buyrunuz .b-cv-cloud:after{left:28px;width:19px;height:19px}',
