reset();
var root=h('div','sim-deger'),cap=h('div','d-cap'),body=h('div','d-body'),nav=h('div','d-nav'),toast=h('div','d-toast');
root.setAttribute('lang','tr');
var host=el.parentNode;
if(!(host&&host.querySelector('.phone-status')))root.appendChild(h('div','d-sb','<span>14:40</span><span>'+SBI+'</span>'));
[cap,body,h('div','d-disc','Değer kredi vermez · teklifler lisanslı ortaktan · örnek veriler'),nav,toast].forEach(function(n){root.appendChild(n)});
el.appendChild(root);

/* caption */
var step=0;
function setCap(i,idle){
if(i<8)step=i;
var d='';for(var k=0;k<8;k++)d+='<i'+(k<=step?' class="on"':'')+'></i>';
cap.innerHTML=dv('d-dots',d)+'<span>'+esc(L[i])+'</span><button class="d-re">'+REPLAY[LG]+'</button>';
cap.classList.toggle('idle',!!idle);
}
var toastT=null;
function flash(t){toast.textContent=t;toast.classList.add('on');if(toastT){var i=UT.indexOf(toastT);if(i>=0){clearTimeout(toastT);UT.splice(i,1)}}toastT=later(function(){toast.classList.remove('on');toastT=null},2200,true)}
function press(b){if(!b)return;b.classList.add('d-pz');later(function(){b.classList.remove('d-pz')},180,true)}
function scrollTo(y){if(reduced){body.scrollTop=y;return}try{body.scrollTo({top:y,behavior:'smooth'})}catch(e){body.scrollTop=y}}
function bottom(){scrollTo(body.scrollHeight)}
