  /* ── drawing helpers ── */
  function rnd(seed) { var s = (seed * 2654435761) >>> 0 || 7; return function () { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; }; }
  function series(seed, n, up, vol) { var r = rnd(seed), v = 50, a = []; for (var i = 0; i < n; i++) { v += (r() - 0.5) * vol + (up ? 0.45 : -0.45); a.push(v); } return a; }
  function pts(a, w, h, pad) {
    var mn = Math.min.apply(null, a), mx = Math.max.apply(null, a), rg = (mx - mn) || 1, o = [];
    for (var i = 0; i < a.length; i++) o.push([pad + i * (w - pad * 2) / (a.length - 1), pad + (1 - (a[i] - mn) / rg) * (h - pad * 2)]);
    return o;
  }
  function line(o) { var d = ''; for (var i = 0; i < o.length; i++) d += (i ? 'L' : 'M') + o[i][0].toFixed(1) + ' ' + o[i][1].toFixed(1); return d; }
  function spark(seed, up, w, h) {
    w = w || 84; h = h || 28; var o = pts(series(seed, 24, up, 4), w, h, 2), col = up ? AC : DN, l = o[o.length - 1];
    return '<svg width="' + w + '" height="' + h + '" viewBox="0 0 ' + w + ' ' + h + '" aria-hidden="true"><path d="' + line(o) + '" fill="none" stroke="' + col + '" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round"/><circle cx="' + l[0].toFixed(1) + '" cy="' + l[1].toFixed(1) + '" r="2.4" fill="' + col + '"/></svg>';
  }
  function chart(seed, up, w, h, lab) {
    var a = series(seed, 40, up, 6), o = pts(a, w, h, 6), col = up ? AC : DN, grid = '', lb = '';
    var mn = Math.min.apply(null, a), mx = Math.max.apply(null, a), rg = (mx - mn) || 1, last = a[a.length - 1], k = lab.pct / rg;
    for (var i = 0; i < 3; i++) { var y = 10 + i * ((h - 20) / 2), v = mn + (1 - (y - 6) / (h - 12)) * rg; grid += '<line x1="0" x2="' + (w - 52) + '" y1="' + y + '" y2="' + y + '" stroke="#243654" stroke-dasharray="3 4"/>'; lb += '<text x="' + (w - 4) + '" y="' + (y + 4) + '" text-anchor="end" font-size="11" fill="' + MU + '" font-family="IBM Plex Mono,monospace">' + lab.cur + fmtTR(lab.px * (1 + (v - last) * k), lab.dec) + '</text>'; }
    var o2 = o.map(function (p) { return [p[0] * (w - 56) / w, p[1]]; }), l2 = o2[o2.length - 1];
    return '<svg width="' + w + '" height="' + h + '" viewBox="0 0 ' + w + ' ' + h + '" aria-hidden="true">' + grid + lb +
      '<path class="e-area" d="' + line(o2) + 'L' + l2[0].toFixed(1) + ' ' + h + 'L' + o2[0][0].toFixed(1) + ' ' + h + 'Z" fill="' + col + '" fill-opacity=".14" opacity="0"/>' +
      '<path class="e-line" d="' + line(o2) + '" fill="none" stroke="' + col + '" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>' +
      '<circle cx="' + l2[0].toFixed(1) + '" cy="' + l2[1].toFixed(1) + '" r="3.5" fill="' + col + '"/><circle cx="' + l2[0].toFixed(1) + '" cy="' + l2[1].toFixed(1) + '" r="7" fill="' + col + '" opacity=".25"/></svg>';
  }
  function donut(size) {
    var r = 40, c = 2 * Math.PI * r, s = '', off = 0;
    ALLOC.forEach(function (a) { var len = c * a[1] / 100; s += '<circle cx="50" cy="50" r="' + r + '" stroke="' + a[2] + '" stroke-dasharray="0 ' + c.toFixed(1) + '" data-len="' + len.toFixed(1) + ' ' + c.toFixed(1) + '" stroke-dashoffset="' + (-off).toFixed(1) + '" transform="rotate(-90 50 50)"/>'; off += len; });
    return '<svg width="' + size + '" height="' + size + '" viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="' + r + '" stroke="#182640"/>' + s + '</svg>';
  }
