        caption(L.s[0], 0);
        at(3000, function () { tapDo('.e-tab[data-s=watch]', function () { show('watch'); caption(L.s[1], 1); }); });
        at(6600, function () { tapDo('.e-wr[data-t=EREGL]', function () { openStock('EREGL', '1G'); caption(L.s[2], 2); }); });
        at(10800, function () { tapDo('.e-seg [data-s=bl]', function () { seg('bl'); caption(L.s[3], 3); }); });
        at(14800, function () { tapDo('.e-tab[data-s=crypto]', function () { openCrypto('BTC'); caption(L.s[4], 4); }); });
        at(17200, function () { tapDo('.e-coin[data-c=ETH]', function () { setCoin('ETH'); }); });
