        at(22400, function () { tapDo('[data-a=shc][data-c=d5]', function () { S.shC = 'd5'; qa('[data-a=shc]').forEach(function (c) { c.classList.toggle('on', c.dataset.c === 'd5'); }); q('.e-sum').textContent = sumText(); }); });
