function cover(el){
ensureCss();
const c=h('div','sim-hexa sim-hexa-cover');
c.innerHTML='<div class="x-cvb">'+board(newGame(4),154,2)+'</div><div class="x-cvl"><div class="x-cvt x-d">'+logo(24)+'HEXAN</div><div class="x-cvs">ONLINE MULTIPLAYER</div><div class="x-cvd">'+PN.map(chip).join('')+'</div><div class="x-cvk">Build · Trade · Settle · Win</div></div>';
el.appendChild(c);
}
