const tT=new Set(),uT=new Set();
function later(fn,ms,ui){const set=ui?uT:tT;const id=setTimeout(()=>{set.delete(id);if(alive)fn();},ms);set.add(id);return id;}
function clr(set){set.forEach(clearTimeout);set.clear();}
function fresh(){st={scr:'welcome',tab:'lobbies',seg:'public',me:'Ayla',email:'',pw:'',su:['','',''],lname:'',maxP:4,tmr:90,priv:false,code:'',room:null,game:null,names:PN.slice(),draft:'',friends:[LB[0],LB[3],LB[1]],fname:'',dname:'',tr:null};}
fresh();
const nm=i=>i?st.names[i]:st.me;
const root=h('div','sim-hexa');
