const em=cap.firstChild,sp=cap.children[1];
cap.classList.toggle('rp',!!mode);em.style.display=mode?'none':'';
if(mode)sp.textContent=mode==='rest'?L.rest:L.paused;else{em.textContent=STEP[i]+'/8';sp.textContent=L.s[i];}
