const suOk=()=>st.su[0].trim()&&st.su[1].trim()&&st.su[2].length>=6;
const R={};
R.welcome=()=>'<div class="x-scr x-wel"><div class="x-wbg">'+board(newGame(4),420,1)+'</div><div class="x-wt x-d">'+logo(46)+'HEXAN</div><div class="x-ws">Online Multiplayer</div><div class="x-card"><div class="h x-d">Welcome</div><div class="p x-m">Sign in to start playing</div>'+btn('email',null,'x-btn','Continue with Email')+'<div class="x-or"><i></i>or<i></i></div>'+btn('google',null,'x-btn w','🔵&nbsp; Continue with Google')+'<div class="x-lk">Don\'t have an account?'+btn('signup',null,'','Sign up')+'</div></div><div class="x-ft">Build • Trade • Settle • Win</div></div>';
function auth(su){
const F=su?[['su0','Display name','e.g. Ayla','text'],['su1','Email','you@example.com','email'],['su2','Password','At least 6 characters','password']]:[['email','Email','you@example.com','email'],['pw','Password','••••••••','password']],t=su?'Sign Up':'Log In';
return'<div class="x-scr">'+hd(t,['welcome','Back'])+'<div class="x-form"><div class="x-ttl x-d">'+t+'</div><div class="x-m" style="margin:4px 0 12px">'+(su?'Create your Hexan account':'Welcome back')+'</div>'+F.map(r=>'<label class="x-lb">'+r[1]+'</label>'+inp(r[0],r[2],su?st.su[+r[0][2]]:st[r[0]],' type="'+r[3]+'"')).join('')+btn(su?'suGo':'login',null,'x-btn'+((su?suOk():st.email.trim()&&st.pw)?'':' dis'),su?'Create Account':'Log In',' style="margin-top:28px"')+'<div class="x-lk">'+(su?'Already have an account?'+btn('email',null,'','Log in'):'No account?'+btn('signup',null,'','Sign up'))+'</div></div></div>';
}
R.login=()=>auth(0);
R.signup=()=>auth(1);
R.tabs=()=>{
const t=st.tab,T=[['lobbies','🎲','Lobbies'],['friends','👥','Friends'],['leaderboard','🏆','Leaderboard'],['profile','👤','Profile']];
return'<div class="x-scr">'+hd(T.find(x=>x[0]===t)[2],null,t==='lobbies'?st.me:null)+'<div class="x-body">'+(t==='lobbies'?rLobbies():t==='friends'?rFriends():t==='leaderboard'?rLeader():rProfile())+'</div>'+(st.game?'<button class="x-rs" data-a="resume" data-k="rs">'+board(st.game,44,1)+'<span><b>'+esc(st.room?st.room.name:'Hexan game')+'</b><small data-k="rss"></small></span><em>Return ›</em></button>':'')+'<div class="x-tb">'+T.map(x=>btn('tab',x[0],x[0]===t?'on':'','<i>'+x[1]+'</i>'+x[2])).join('')+'</div></div>';
};
function rLobbies(){
const pub=st.seg==='public';
return'<div class="x-seg">'+btn('seg','public',pub?'on':'','<i>🌐</i>Public')+btn('seg','private',pub?'':'on','<i>🔒</i>Private Code')+'</div>'+(pub?'<div class="x-scroll" style="padding-top:6px">'+LOB.map((l,i)=>btn('join',i,'x-lc','<div class="l"><b class="n">'+esc(l.n)+'</b><span class="m">standard&nbsp; •&nbsp; '+l.t+'s/turn</span><div class="x-dots">'+Array.from({length:l.x},(_,j)=>j<l.m.length?chip(l.m[j],j+1):'<i></i>').join('')+'</div></div><div class="x-lr">'+l.m.length+'/'+l.x+'<span class="x-join">JOIN</span></div>')).join('')+'<div class="x-empty">Pull to refresh, or create one below.</div></div>':'<div class="x-priv"><div class="h x-d">Got an invite code?</div><p class="x-m">Enter the 6-character code your friend shared with you.</p><input class="x-code x-d" data-i="code" maxlength="6" placeholder="ABC123" autocomplete="off" value="'+esc(st.code)+'">'+btn('joinCode',null,'x-btn'+(st.code.length===6?'':' dis'),'Join Game')+'</div>')+btn('create',null,'x-create','+ Create New Lobby');
}
const rFriends=()=>'<div class="x-add"><small>ADD FRIEND BY DISPLAY NAME</small><div class="x-row">'+inp('fname','display name',st.fname)+btn('addF',null,'x-sbtn'+(st.fname.trim()?'':' dis'),'Add')+'</div></div><div class="x-scroll">'+st.friends.map((r,i)=>'<div class="x-fr"><div><b>'+esc(r[0])+'</b><small>'+pl(r[1],'win')+' • '+pl(r[2],'game')+'</small></div>'+btn('rmF',i,'','remove')+'</div>').join('')+(st.friends.length?'':'<div class="x-empty">No friends yet. Add someone by their display name above.</div>')+'</div>';
const rLeader=()=>'<div class="x-scroll"><div class="x-intro">Top players by wins.</div>'+LB.map((r,i)=>{const me=r[0]==='Ayla';return'<div class="x-lbr'+(me?' me':'')+'" style="animation-delay:'+i*70+'ms"><span class="rk">#'+(i+1)+'</span><span class="nm">'+esc(me?st.me+' (you)':r[0])+'</span><div class="w"><b>'+pl(r[1],'win')+'</b>'+r[2]+' played</div></div>';}).join('')+'</div>';
const rProfile=()=>'<div class="x-pf"><label class="x-lb">Display name</label><div class="x-row">'+inp('dname','',st.dname||st.me,' maxlength="20"')+btn('saveN',null,'x-sbtn'+(st.dname.trim()&&st.dname.trim()!==st.me?'':' dis'),'Save')+'</div><label class="x-lb">Email</label><div style="color:#fff">'+esc(st.email.trim()||'ayla@example.com')+'</div>'+btn('signOut',null,'x-so','Sign out')+'</div>';
R.create=()=>'<div class="x-scr">'+hd('Create Lobby',['tabs','Lobbies'])+'<div class="x-scroll"><div class="x-cl"><label class="x-lb">Lobby name</label>'+inp('lname','e.g. Friday Night Hexan',st.lname,' maxlength="32"')+'<label class="x-lb">Max players</label><div class="x-pills">'+[3,4,5,6].map(n=>btn('maxP',n,st.maxP===n?'on':'',n)).join('')+'</div>'+'<label class="x-lb">Turn timer</label><div class="x-hint">Each player has this many seconds per turn</div><div class="x-pills">'+[60,90,120,150].map(n=>btn('tmr',n,st.tmr===n?'on':'',n+'s')).join('')+'</div>'+'<label class="x-lb">Map</label><div class="x-map"><div><b>Standard</b><small class="x-m">Classic 19-hex layout</small></div><em>✓</em></div>'+'<div class="x-prow"><div><label class="x-lb">Private lobby</label><div class="x-hint">Hidden from public list — friends join via the invite code</div></div>'+btn('priv',null,'x-sw'+(st.priv?' on':''),'',' aria-label="Private lobby"')+'</div>'+btn('mk',null,'x-btn','Create Lobby',' style="margin-top:24px;font-size:16px;min-height:52px"')+'</div></div></div>';
R.room=()=>{
const r=st.room,rd=r.mem.filter(m=>m.rd).length;
const s='<div class="x-scr">'+hd('Lobby')+'<div class="x-rh"><div><div class="t x-d">'+esc(r.name)+'</div><small class="x-m">'+rd+'/'+r.mem.length+' ready · '+(r.mem.length<r.max?'waiting for players…':'lobby full')+'</small></div>'+btn('leave',null,'','Leave')+'</div>'+btn('share',null,'x-cb','<div><small>INVITE CODE</small><b class="x-d" style="display:block">'+r.code+'</b></div><em>Share ↗</em>')+'<div class="x-grid">'+Array.from({length:r.max},(_,i)=>{const m=r.mem[i];return m?'<div class="x-slot'+(m.j?' j':'')+'" style="border-color:'+PC[m.p]+'"><i class="av" style="background:'+PC[m.p]+'">'+esc(m.n[0])+'</i><div class="bd"><div class="nm">'+esc(m.n)+(m.host?' 👑':'')+(m.p?'':' <span class="you">YOU</span>')+'</div>'+(m.p?'<span class="rd'+(m.rd?' ok':'')+'">'+(m.rd?'Ready ✓':'Not ready')+'</span>':btn('ready',null,'rd'+(m.rd?' ok':''),m.rd?'Ready ✓':'Tap when ready'))+'</div></div>':'<div class="x-slot e"><i>👤</i><span>Waiting…</span></div>';}).join('')+'</div>'+'<div class="x-set"><div><small>MAP</small><b>standard</b></div><div><small>TURN</small><b>'+r.tmr+'s</b></div><div><small>PLAYERS</small><b>'+r.mem.length+'/'+r.max+'</b></div>'+btn('chat',null,'','<small>CHAT</small><b>💬 '+r.chat.length+'</b>')+'</div>'+(r.showChat?'<div class="x-chat">'+(r.chat.length?r.chat.map(c=>'<p><b>'+esc(c[0])+': </b>'+esc(c[1])+'</p>').join(''):'<p class="x-m" style="text-align:center;font-style:italic">No messages yet</p>')+'<div class="x-crow"><input data-i="draft" placeholder="Say something…" maxlength="200" autocomplete="off" value="'+esc(st.draft)+'">'+btn('send',null,'','↑')+'</div></div>':'')+(r.host?btn('start',null,'x-start','▶&nbsp; Start Game'):'<div class="x-wait">Waiting for host to start…</div>')+'</div>';
r.mem.forEach(m=>{m.j=0;});
return s;
};
R.game=()=>'<div class="x-scr"><div class="x-top"><div class="tl"><b class="x-d" data-k="turn"></b><small data-k="sub"></small></div><span class="x-tm" data-k="tm"></span>'+btn('exit',null,'','✕',' aria-label="Leave game"')+'</div>'+'<div class="x-vp"><small>VICTORY POINTS</small><div data-k="pips"></div><b data-k="vp"></b></div><div class="x-bd">'+board(st.game,384)+'</div><div class="x-log" data-k="log"></div><div class="x-dice" data-k="dice"></div>'+'<div class="x-res" data-k="res">'+RES.map(r=>'<div class="x-rc" data-r="'+r+'"><i style="background:'+RC[r]+'">'+RE[r]+'</i><b>0</b></div>').join('')+'</div>'+'<div class="x-ab">'+[['roll','Roll'],['build','Build'],['trade','Trade'],['end','End Turn']].map(b=>btn(b[0],null,b[0]==='end'?'hl':'',b[1],' data-k="b'+b[0]+'"')).join('')+'</div><div class="x-bk" data-a="shut"></div><div class="x-sh" data-k="sh"></div></div>';
function go(s,keep){
st.scr=s;K={};
view.innerHTML=R[s]();
if(!keep)scr().classList.add('x-in');
view.querySelectorAll('[data-k]').forEach(e=>{K[e.getAttribute('data-k')]=e;});
if(s==='game')upGame();
upResume();
}
function toast(msg){const t=h('div','x-toast',esc(msg));root.appendChild(t);later(()=>t.remove(),2300,1);}
const tog=(e,d)=>{if(e)e.classList.toggle('dis',!!d);};
function upGame(){
const g=st.game;if(!g||st.scr!=='game')return;
K.turn.textContent=g.turn?nm(g.turn)+'\'s turn':'YOUR TURN';
K.sub.innerHTML=Array.from({length:g.n},(_,i)=>'<em style="color:'+PC[i]+'">'+esc(nm(i))+':'+vp(g,i)+'</em>').join('&nbsp; •&nbsp; ');
const my=vp(g,0)+'/10';
if(K.vp.textContent&&K.vp.textContent!==my){K.vp.classList.remove('bump');void K.vp.offsetWidth;K.vp.classList.add('bump');}
K.vp.textContent=my;
K.pips.innerHTML='<i class="on"></i>'.repeat(vp(g,0))+'<i></i>'.repeat(Math.max(0,10-vp(g,0)));
K.tm.textContent=g.t+'s';
RES.forEach(r=>{K.res.querySelector('[data-r="'+r+'"] b').textContent=g.res[r];});
const mine=!g.turn&&g.mode!=='rob';
tog(K.broll,g.turn||g.rolled);tog(K.bbuild,!(mine&&g.rolled));tog(K.btrade,!(mine&&g.rolled));tog(K.bend,!(mine&&g.rolled));
scr().classList.toggle('pm',!!g.mode&&g.mode!=='rob');
K.pc.innerHTML=pieces(g);K.hi.innerHTML=hints(g);g.fresh=null;
K.log.innerHTML=g.log.slice(-2).map(x=>'<p>'+esc(x)+'</p>').join('');
dbox();
}
function dbox(rolling){
const g=st.game,m=g.mode,d=g.dice;if(!K.dice)return;
K.dice.innerHTML=rolling?'<span class="sh">'+die(rnd6())+'</span><span class="sh">'+die(rnd6())+'</span><span class="x-dt">Rolling…</span>':m&&m!=='rob'?'<span class="x-ht">'+(m==='road'?'Tap a glowing edge to place your road':m==='set'?'Tap a glowing corner for your settlement':'Tap a settlement to upgrade it')+'</span>'+btn('cancel',null,'','Cancel'):d?die(d[0])+die(d[1])+'<span class="x-dt">'+d[0]+' + '+d[1]+' = '+(d[0]+d[1])+'</span>'+(m==='rob'?'<em class="x-7">Move the robber</em>':''):g.turn?'<span class="x-dt" style="font-size:15px">'+esc(nm(g.turn))+' is rolling…</span>':'<span class="x-dt">🎲 — roll the dice —</span>';
}
function addRes(delta){
const g=st.game;
for(const r in delta){
if(!delta[r])continue;
g.res[r]+=delta[r];
if(st.scr==='game'){const c=K.res.querySelector('[data-r="'+r+'"]'),b=c.querySelector('b'),s=h('span','x-fl'+(delta[r]>0?' up':''),(delta[r]>0?'+':'')+delta[r]);c.appendChild(s);later(()=>s.remove(),1150,1);b.classList.remove('bump');void b.offsetWidth;b.classList.add('bump');}
}
upGame();
}
function hot(t){
if(st.scr!=='game')return;
H.forEach(x=>{if(x.num===t)root.querySelectorAll('[data-t="'+x.i+'"]').forEach(e=>e.classList.add('hot'));});
later(()=>root.querySelectorAll('.hot').forEach(e=>e.classList.remove('hot')),1300,1);
}
function produce(g,t){const o={};H.forEach(x=>{if(x.num===t&&g.robber!==x.i)x.v.forEach(v=>{if(g.set[v]===0)o[x.res]=(o[x.res]||0)+(g.city[v]?2:1);});});return o;}
function roll(d1,d2){
const g=st.game;if(!g||g.turn||g.rolled)return;
g.rolled=true;upGame();
let n=0;
const tick=()=>{
if(st.game!==g)return;
if(n++<7){dbox(1);later(tick,95,1);return;}
d1=d1||rnd6();d2=d2||rnd6();g.dice=[d1,d2];
const t=d1+d2;g.log.push(nm(0)+' rolled '+d1+' + '+d2+' = '+t);
if(t===7){g.mode='rob';upGame();}else{hot(t);addRes(produce(g,t));}
};
tick();
}
function robTo(g,i){g.robber=i;if(K.rb){K.rb.style.transform=at(i);root.querySelectorAll('g[data-t]').forEach(e=>e.classList.toggle('x-rbd',+e.getAttribute('data-t')===i));}g.log.push('Robber moved to '+H[i].res+(H[i].num?' '+H[i].num:''));}
function moveRobber(i,pick){
const g=st.game;if(!g||g.mode!=='rob'||i===g.robber)return;
g.mode=null;robTo(g,i);upGame();
const vic=H[i].v.map(v=>g.set[v]).filter(p=>p>0)[0];
if(vic)later(()=>{if(st.game!==g)return;const r=pick||RES[Math.floor(Math.random()*5)];g.log.push(nm(0)+' stole 1 '+RE[r]+' '+r+' from '+nm(vic));addRes({[r]:1});},800,1);
}
const afford=c=>Object.keys(c).every(r=>st.game.res[r]>=c[r]);
function pay(c){const d={};for(const r in c)d[r]=-c[r];addRes(d);}
function openSheet(kind){
const g=st.game;let s='<div class="x-gr"></div><div class="x-shh"><b class="x-d">'+(kind==='build'?'Build':kind==='trade'?'Trade':'Leave game?')+'</b>'+btn('shut',null,'','✕',' aria-label="Close"')+'</div>';
if(kind==='leave')s+='<div class="x-shs">You will be removed from the lobby.</div><div class="x-lv">'+btn('shut',null,'','Cancel')+btn('leave',null,'','Leave')+'</div>';
else if(kind==='build'){
s+='<div class="x-shs">Costs come straight out of your hand.</div>'+[['road','Road','Extends your network',roadSpots(g)],['settlement','Settlement','+1 victory point',setSpots(g),'Needs a road to a free corner'],['city','City','Upgrade a settlement · +1 VP',citySpots(g)]].map(r=>{
const c=COST[r[0]],ok=afford(c)&&r[3].length;
return'<div class="x-br">'+icon(r[0])+'<div class="tx"><b>'+r[1]+'</b><small>'+(r[4]&&!r[3].length?r[4]:r[2])+'</small><div class="x-cost">'+Object.keys(c).map(x=>'<span'+(g.res[x]<c[x]?' class="no"':'')+'>'+RE[x]+' '+c[x]+'</span>').join('')+'</div></div>'+btn('b',r[0],ok?'':'dis','Build')+'</div>';
}).join('');
}else{
const t=st.tr,row=(a,o,sub)=>'<div class="x-trow">'+RES.map(r=>btn(a,r,'x-tc'+(o[r]?' on':''),'<i style="background:'+RC[r]+'">'+RE[r]+'</i><b>'+(o[r]||0)+'</b>'+sub(r))).join('')+'</div>';
s+='<div class="x-shs">Offer to all players · tap a card to add it</div><div class="x-tl2">YOU GIVE</div>'+row('tg',t.give,r=>'of '+g.res[r])+'<div class="x-tl2">YOU GET</div>'+row('tt',t.get,r=>r)+(t.resp?'<div style="margin-top:10px">'+t.resp.map(x=>'<div class="x-rp"><i style="background:'+PC[x[0]]+'"></i>'+esc(nm(x[0]))+'<span class="'+(x[1]>0?'ok">Accepted ✓':x[1]<0?'no">Declined':'">Thinking…')+'</span></div>').join('')+'</div>':btn('offer',null,'x-btn'+(RES.some(r=>t.give[r])&&RES.some(r=>t.get[r])?'':' dis'),'Send offer',' style="margin-top:14px"'));
}
K.sh.innerHTML=s;scr().classList.add('sho');
}
function shut(){st.tr=null;if(scr())scr().classList.remove('sho');}
function placeEdge(k){const g=st.game;if(g.mode!=='road'||roadSpots(g).indexOf(k)<0)return;g.road[k]=0;g.fresh='e'+k;g.mode=null;g.log.push(nm(0)+' built a road');pay(COST.road);}
function placeVertex(v){
const g=st.game,city=g.mode==='city';v=+v;
if((city?citySpots(g):g.mode==='set'?setSpots(g):[]).indexOf(v)<0)return;
if(city)g.city[v]=1;else g.set[v]=0;
g.fresh='v'+v;g.mode=null;g.log.push(nm(0)+' built a '+(city?'city':'settlement')+' · '+vp(g,0)+'/10 VP');pay(COST[city?'city':'settlement']);
}
function offer(who){
const g=st.game,t=st.tr;if(!t||t.resp)return;
const opp=Array.from({length:g.n-1},(_,i)=>i+1),sum=o=>RES.reduce((a,r)=>a+(o[r]||0),0);
if(who==null)who=sum(t.give)>=sum(t.get)?opp[Math.floor(Math.random()*opp.length)]:-1;
t.resp=opp.map(p=>[p,0]);openSheet('trade');
opp.forEach((p,i)=>later(()=>{if(st.tr!==t)return;t.resp[i][1]=p===who?1:-1;openSheet('trade');},350+i*350,1));
later(()=>{
if(st.tr!==t)return;
const ls=o=>RES.filter(r=>o[r]).map(r=>o[r]+' '+RE[r]).join(' ');
if(who>0){const d={};RES.forEach(r=>{d[r]=(t.get[r]||0)-(t.give[r]||0);});g.log.push('Traded '+ls(t.give)+' → '+ls(t.get)+' with '+nm(who));addRes(d);}else g.log.push('Nobody took the offer');
later(()=>{if(st.tr===t){shut();upGame();}},700,1);
},500+opp.length*350,1);
}
function opp(g,p){
if(st.game!==g)return;
g.turn=p;g.dice=null;upGame();upResume();
later(()=>{
if(st.game!==g)return;
const d1=rnd6(),d2=rnd6(),t=d1+d2;g.dice=[d1,d2];g.log.push(nm(p)+' rolled '+d1+' + '+d2+' = '+t);
if(t===7){const c=H.filter(x=>x.i!==g.robber&&x.v.every(v=>g.set[v]!==p));robTo(g,c[Math.floor(Math.random()*c.length)].i);upGame();}else{hot(t);addRes(produce(g,t));}
later(()=>{if(st.game!==g)return;if(p<g.n-1)opp(g,p+1);else{g.turn=0;g.dice=null;g.t=st.room?st.room.tmr:90;upGame();upResume();}},900,1);
},700,1);
}
function upResume(){const g=st.game;if(!K.rss||!g)return;K.rss.textContent=(g.turn?nm(g.turn)+'\'s turn':'Your turn')+' · you '+vp(g,0)+'/10 VP';K.rs.classList.toggle('yt',!g.turn);}
function openRoom(r){
st.room=r;st.draft='';go('room');
const re=()=>{if(st.room===r&&st.scr==='room')go('room',1);};
const next=()=>{
if(st.room!==r)return;
if(r.pending.length&&r.mem.length<Math.min(r.max,4)){const m=r.pending.shift();m.j=1;r.mem.push(m);re();later(()=>{m.rd=1;re();},700,1);later(next,420,1);}
else if(r.talk.length){r.chat.push(r.talk.shift());re();later(next,520,1);}
else if(!r.host)later(()=>{if(st.room===r&&st.scr==='room'){toast(r.mem[0].n+' started the game');startGame();}},900,1);
};
later(next,450,1);
}
function startGame(){const r=st.room;r.mem.forEach(m=>{if(m.p)st.names[m.p]=m.n;});st.game=newGame(Math.max(2,Math.min(4,r.mem.length)));st.game.t=r.tmr;go('game');}
