      const tick = () => { if (g !== S.gen || !S.scan) return; const p = Math.min(1, (Date.now() - S.scan.t0) / S.scan.dur); updScan(p); if (p < 1) later(tick, 70); else finishSearch(fromTour); };
      if (rm) finishSearch(fromTour); else later(tick, 40);
