      const src = Q[key];
      S.chat.push({ id: ++seq, role: 'u', text });
      const m = { id: ++seq, role: 'a', words: src.a.split(' '), shown: 0, chart: src.chart || null, chartAt: src.chartAt || 0, chartOn: false, disc: true, done: false };
      S.chat.push(m);
