/* ---------- helpers ---------- */
const cm = (x, d) => x.toFixed(d).replace('.', ',');
const dt = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const mon = (n) => n >= 1e6 ? '₺' + cm(n / 1e6, 2) + ' mn' : '₺' + cm(n / 1e3, 1) + ' bin';
const ax = (n) => n >= 1e6 ? '₺' + cm(n / 1e6, 1) + ' mn' : '₺' + Math.round(n / 1e3) + ' bin';
const pc = (x, d) => '%' + cm(x, d || 0);
const sg = (x) => (x >= 0 ? '+' : '−') + '%' + cm(Math.abs(x), 0);
const f1 = (x) => x.toFixed(1);
const pth = (a) => a.map((p, i) => (i ? 'L' : 'M') + f1(p[0]) + ' ' + f1(p[1])).join('');
const svg = (w, h, s) => `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">${s}</svg>`;
const T = (x, y, s, a, c) => `<text x="${f1(x)}" y="${f1(y)}"${a ? ` text-anchor="${a}"` : ''}${c ? ` class="${c}"` : ''}>${s}</text>`;
const L = (x1, y1, x2, y2, st, w, da) => `<line x1="${f1(x1)}" y1="${f1(y1)}" x2="${f1(x2)}" y2="${f1(y2)}" stroke="${st}" stroke-width="${w || 1}"${da ? ` stroke-dasharray="${da}"` : ''}/>`;
const roas = (P, d) => 100 * Math.pow((d + 1) / (P + 1), 0.45);
const IC = (p) => `<svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${p}</svg>`;
function spark(v, w, h, c, th) {
const all = th == null ? v : v.concat([th]), mn = Math.min.apply(0, all), mx = Math.max.apply(0, all), r = (mx - mn) || 1;
const X = (i) => 2 + i / (v.length - 1) * (w - 6), Y = (x) => h - 3 - (x - mn) / r * (h - 6);
return svg(w, h, (th == null ? '' : L(0, Y(th), w, Y(th), '#9AA3A8', 1, '3 3')) + `<path d="${pth(v.map((x, i) => [X(i), Y(x)]))}" fill="none" stroke="${c}" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round"/><circle cx="${f1(X(v.length - 1))}" cy="${f1(Y(v[v.length - 1]))}" r="2.6" fill="${c}"/>`);
}
function chip(x, y, s, col, bg, anchorRight) {
const w = s.length * 6.3 + 16, x0 = anchorRight ? x - w : x;
return `<g class="pop"><rect x="${f1(x0)}" y="${f1(y)}" width="${f1(w)}" height="23" rx="6" fill="${bg}" stroke="${col}" stroke-opacity=".45"/>${T(x0 + w / 2, y + 15.5, s, 'middle', 's')}</g>`.replace('<text ', `<text style="fill:${col};font-weight:600" `);
}

