/* ---------- chart builders ---------- */
function weekSvg() {
const W = 648, H = 132, B = H - 20, mx = 540; let s = '';
[100, 200, 300, 400, 500].forEach((v) => { s += L(30, B - v / mx * B, W, B - v / mx * B, C.gr); });
s += T(24, B - 400 / mx * B + 4, '400', 'end') + T(24, B - 200 / mx * B + 4, '200', 'end') + L(30, B, W, B, '#C9D0D2');
KP[0][4].forEach((v, i) => {
const gx = 34 + i * (W - 34) / 12, r = v * WR[i], hs = v / mx * B, hr = r / mx * B;
s += `<rect x="${f1(gx + 9)}" y="${f1(B - hs)}" width="14" height="${f1(hs)}" rx="2" fill="${C.sp}"><title>H${27 + i} · harcama ₺${Math.round(v)} bin · örnek</title></rect><rect x="${f1(gx + 25)}" y="${f1(B - hr)}" width="14" height="${f1(hr)}" rx="2" fill="${C.rt}"><title>H${27 + i} · tahmini D180 getiri ₺${Math.round(r)} bin · örnek</title></rect>` + T(gx + 24, H - 4, 'H' + (27 + i), 'middle');
});
return svg(W, H, s);
}
