const tour = {
paused: false, ids: new Set(),
pause() {
if (this.paused) return; this.paused = true;
this.ids.forEach((id) => { clearTimeout(id); timers.delete(id); }); this.ids.clear();
if (S.stage < 4) { S.stage = 4; S.ty = T0.length; if (S.v === 'ai') renderRecs(); }
caption(7);
}
};
const at = (ms, fn) => { const id = later(() => { tour.ids.delete(id); if (!tour.paused) fn(); }, ms); tour.ids.add(id); };
