root.className='sim-osint'+(rm?' rm':'');root.lang='tr';
const S={tab:'tekil',tur:'kisi',ad:'',il:'',auto:true,scan:null,result:null,rows:['done','done','wait','wait','wait'],list:true,batch:false,tauto:true,dark:false,logged:false,rem:true};
