'.sim-pati .p-pg{animation:simPatiIn .32s ease both}',
'@keyframes simPatiIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}',
'.sim-pati .p-nav{position:absolute;left:0;right:0;bottom:0;height:84px;background:#FFFDF9;border-top:1px solid #EFE4D6;display:flex;justify-content:space-around;padding:8px 8px 0;z-index:4}',
'.sim-pati .p-ni{display:flex;flex-direction:column;align-items:center;gap:3px;width:78px;height:54px;color:#7A665A;font-size:11px;font-weight:800;padding-top:6px;border-radius:16px;transition:transform .15s}',
'.sim-pati .p-ni svg{width:24px;height:24px}',
