/* page header */
'.sim-pati .p-hdr{display:flex;align-items:center;gap:10px;margin-bottom:16px;min-height:38px}',
'.sim-pati .p-back{width:38px;height:38px;border-radius:13px;background:#F3EADF;display:flex;align-items:center;justify-content:center;flex:none;transition:transform .15s}',
'.sim-pati .p-back svg{width:22px;height:22px}',
