'.sim-pati .p-petpill{display:flex;align-items:center;gap:6px;padding:4px 10px 4px 4px;border-radius:999px;background:#FFFDF9;border:1px solid #F0E6DA;font-size:12.5px;font-weight:800;flex:none}',
