/* cards */
'.sim-pati .p-card{background:#FFFDF9;border:1px solid #F0E6DA;border-radius:22px;padding:16px;box-shadow:0 6px 18px rgba(107,78,61,.07)}',
'.sim-pati .p-h1{font-size:30px;line-height:1.02;margin-top:4px}',
