'.sim-pati .p-bell i{position:absolute;top:9px;right:10px;width:8px;height:8px;border-radius:50%;background:#E07A3F;border:2px solid #FFFDF9}',
'.sim-pati .p-pet{display:flex;gap:14px;align-items:center;margin-top:18px;cursor:pointer}',
'.sim-pati .p-av{width:74px;height:74px;border-radius:24px;background:#E9EDF1;display:flex;align-items:center;justify-content:center;flex:none;overflow:hidden}',
'.sim-pati .p-av svg{width:100%;height:100%}',
