'.sim-pati .p-tag{font-size:11.5px;font-weight:800;padding:4px 8px;border-radius:8px;background:#F3EADF;color:#5C4A3E;line-height:1.2}',
'.sim-pati .p-tag.s{background:#DDEBE0;color:#24462E}',
'.sim-pati .p-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}',
'.sim-pati .p-qa{border-radius:20px;padding:14px;min-height:104px;display:flex;flex-direction:column;justify-content:space-between;gap:10px;font-weight:800;font-size:14.5px;line-height:1.15;transition:transform .15s}',
'.sim-pati .p-qa small{display:block;font-size:11.5px;font-weight:700;opacity:.75;margin-top:3px}',
'.sim-pati .p-qa.a{background:#E07A3F;color:#1F1512}',
'.sim-pati .p-qa.s{background:#DDEBE0;color:#24462E}',
'.sim-pati .p-qa.c{background:#EADFD2;color:#3B2F2A}',
'.sim-pati .p-qa.w{background:#FFFDF9;border:1px solid #F0E6DA;color:#3B2F2A}',
'.sim-pati .p-ic{width:36px;height:36px;border-radius:12px;background:rgba(255,255,255,.55);display:flex;align-items:center;justify-content:center;flex:none}',
'.sim-pati .p-ic svg{width:21px;height:21px}',
'.sim-pati .p-next{display:flex;align-items:center;gap:12px;margin-top:12px;padding:14px 16px}',
'.sim-pati .p-next .p-ic{background:#FBE6D8;color:#B5551C}',
'.sim-pati .p-bar{height:8px;border-radius:4px;background:#F0E6DA;overflow:hidden;margin-top:10px}',
'.sim-pati .p-bar i{display:block;height:100%;border-radius:4px;background:#8FB89A;transition:width .4s ease}',
