'.sim-pati .p-photo .p-ph-box small{position:absolute;right:calc(100% + 8px);top:1px;font-size:11px;font-weight:800;color:#fff;background:rgba(31,21,18,.55);padding:1px 6px;border-radius:6px;line-height:15px;white-space:nowrap}',
