'.sim-pati .p-photo .p-ph-ok{position:absolute;left:10px;top:10px;display:flex;align-items:center;gap:5px;background:rgba(255,255,255,.9);border-radius:8px;padding:4px 8px;font-size:11.5px;color:#24462E;font-weight:800}',
'.sim-pati .p-photo .p-ph-ok svg{width:14px;height:14px}',
'.sim-pati .p-hint{display:flex;align-items:center;justify-content:center;gap:6px;margin-top:12px;font-size:12.5px;color:#7A665A;font-weight:700;text-align:center;line-height:1.35}',
'.sim-pati .p-hint.warn{color:#9B3A22}',
/* thinking */
