'.sim-pati .p-think .p-sub{padding:0 24px}',
'.sim-pati .p-tl2{width:100%;margin-top:8px;text-align:left;padding:4px 16px 2px}',
'.sim-pati .p-tr{display:flex;align-items:center;gap:12px;padding:11px 0;border-bottom:1px solid #F0E6DA;font-size:14px;font-weight:800;line-height:1.3}',
'.sim-pati .p-tr:last-child{border:0}',
'.sim-pati .p-tr i{width:24px;height:24px;border-radius:50%;border:2.5px solid #EADFD2;border-top-color:#E07A3F;flex:none;animation:simPatiSpin .9s linear infinite;display:flex;align-items:center;justify-content:center;color:#fff;transition:background .2s,border-color .2s}',
'.sim-pati .p-tr i svg{width:14px;height:14px;opacity:0}',
'.sim-pati .p-tr.ok i{animation:none;border-color:#8FB89A;background:#8FB89A}',
'.sim-pati .p-tr.ok i svg{opacity:1}',
'.sim-pati .p-tr small{display:block;font-size:12.5px;color:#7A665A;font-weight:700;margin-top:1px}',
'@keyframes simPatiSpin{to{transform:rotate(360deg)}}',
'.sim-pati .p-last{display:flex;align-items:center;gap:12px;margin-top:16px;padding:12px 14px}',
'.sim-pati .p-last .p-ic{background:#DDEBE0;color:#24462E}',
'.sim-pati .p-think .p-av{width:96px;height:96px;border-radius:32px}',
'.sim-pati .p-pd{display:flex;gap:7px}',
'.sim-pati .p-pd i{display:block;width:9px;height:9px;border-radius:50%;background:#E07A3F;animation:simPatiPulse 1s infinite ease-in-out}',
'.sim-pati .p-pd i:nth-child(2){animation-delay:.16s}.sim-pati .p-pd i:nth-child(3){animation-delay:.32s}',
'@keyframes simPatiPulse{0%,100%{transform:scale(.55);opacity:.35}50%{transform:scale(1);opacity:1}}',
/* result */
'.sim-pati .p-band{border-radius:22px;padding:16px 18px;background:#F7E3C4;color:#5A3A0E;position:relative;overflow:hidden}',
'.sim-pati .p-band.low{background:#DDEBE0;color:#24462E}',
'.sim-pati .p-band .p-eye{color:#8A5A12;display:flex;align-items:center;gap:6px}',
'.sim-pati .p-band.low .p-eye{color:#2F6A3F}',
'.sim-pati .p-band .p-eye i{width:8px;height:8px;border-radius:50%;background:#E07A3F;display:block}',
'.sim-pati .p-band.low .p-eye i{background:#3F7A50}',
'.sim-pati .p-band .p-bt{font-size:24px;line-height:1.05;margin-top:6px}',
'.sim-pati .p-band .p-bs{font-size:13px;margin-top:8px;opacity:.85;font-weight:700;line-height:1.4}',
'.sim-pati .p-band .p-bp{position:absolute;right:-14px;top:-16px;opacity:.16}',
'.sim-pati .p-steps{margin-top:6px}',
'.sim-pati .p-step{display:flex;gap:12px;padding:12px 0;border-bottom:1px solid #F0E6DA;align-items:flex-start;font-size:14px;line-height:1.4;font-weight:600}',
'.sim-pati .p-step:last-child{border:0;padding-bottom:4px}',
'.sim-pati .p-step b{width:28px;height:28px;border-radius:10px;background:#DDEBE0;color:#24462E;display:flex;align-items:center;justify-content:center;font-size:13px;flex:none;font-weight:800;margin-top:1px}',
'.sim-pati .p-esc{border-radius:20px;padding:14px 16px;background:#F8E4DE;border:1px solid #EFC7BB;color:#9B3A22;margin-top:12px}',
'.sim-pati .p-esc .p-eye{color:#9B3A22;display:flex;align-items:center;gap:6px}',
'.sim-pati .p-esc ul{list-style:none;margin:8px 0 12px;display:grid;gap:5px;font-size:13.5px;font-weight:700;line-height:1.35}',
'.sim-pati .p-esc li{display:flex;gap:8px;align-items:flex-start}',
'.sim-pati .p-esc li:before{content:"";width:6px;height:6px;border-radius:50%;background:#C9503A;flex:none;margin-top:7px}',
'.sim-pati .p-esc .p-btn{background:#C9503A;color:#fff;height:42px;border-radius:13px;font-size:14px}',
'.sim-pati .p-disc{display:flex;gap:10px;align-items:flex-start;margin-top:14px;padding:12px 14px;border-radius:16px;background:#F3EADF;font-size:12.5px;line-height:1.4;color:#5C4A3E;font-weight:700}',
'.sim-pati .p-disc svg{width:18px;height:18px;flex:none;margin-top:1px;color:#7A665A}',
'.sim-pati .p-acts{display:grid;gap:10px;margin-top:14px}',
/* today */
'.sim-pati .p-prog{display:flex;align-items:center;gap:14px}',
'.sim-pati .p-ring{width:64px;height:64px;border-radius:50%;background:conic-gradient(#8FB89A var(--p,20%),#F0E6DA 0);display:flex;align-items:center;justify-content:center;flex:none}',
'.sim-pati .p-ring b{width:48px;height:48px;border-radius:50%;background:#FFFDF9;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:800}',
'.sim-pati .p-tasks{display:grid;gap:8px;margin-top:10px}',
'.sim-pati .p-task{display:flex;align-items:center;gap:12px;padding:12px 14px;background:#FFFDF9;border:1px solid #F0E6DA;border-radius:18px;transition:transform .15s}',
'.sim-pati .p-task .p-ck{width:26px;height:26px;border-radius:9px;border:2px solid #DCCFC0;flex:none;display:flex;align-items:center;justify-content:center;color:#fff;transition:background .18s,border-color .18s}',
'.sim-pati .p-task .p-ck svg{width:16px;height:16px;opacity:0;transition:opacity .18s}',
'.sim-pati .p-task.done .p-ck{background:#8FB89A;border-color:#8FB89A}',
'.sim-pati .p-task.done .p-ck svg{opacity:1}',
'.sim-pati .p-task .p-tt{font-size:15px;font-weight:800;line-height:1.2}',
'.sim-pati .p-task.done .p-tt{text-decoration:line-through;color:#7A665A}',
'.sim-pati .p-task .p-ts{font-size:12.5px;color:#7A665A;font-weight:700;margin-top:1px}',
'.sim-pati .p-task .p-tk{margin-left:auto;color:#7A665A;flex:none}',
'.sim-pati .p-task .p-tk svg{width:20px;height:20px}',
'.sim-pati .p-task.nw{border-color:#F2C9B2;background:#FFF6EF}',
'.sim-pati .p-sw{width:44px;height:26px;border-radius:13px;background:#DCCFC0;position:relative;flex:none;transition:background .2s}',
'.sim-pati .p-sw:after{content:"";position:absolute;top:3px;left:3px;width:20px;height:20px;border-radius:50%;background:#fff;transition:transform .2s;box-shadow:0 1px 3px rgba(0,0,0,.2)}',
'.sim-pati .p-sw.on{background:#8FB89A}.sim-pati .p-sw.on:after{transform:translateX(18px)}',
'.sim-pati .p-note{margin-top:12px;padding:14px 16px;border-radius:18px;background:#EADFD2;font-size:13px;line-height:1.45;font-weight:700;color:#3B2F2A}',
'.sim-pati .p-note b{display:block;font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:#7A665A;margin-bottom:4px}',
/* timeline */
'.sim-pati .p-tl{position:relative;padding-left:28px;margin-top:6px}',
'.sim-pati .p-tl:before{content:"";position:absolute;left:8px;top:10px;bottom:10px;width:2px;background:#EADFD2;border-radius:1px}',
'.sim-pati .p-te{position:relative;padding:0 0 18px;animation:simPatiIn .32s ease both}',
'.sim-pati .p-te i{position:absolute;left:-26px;top:3px;width:16px;height:16px;border-radius:50%;background:#FBF6EF;border:3px solid #8FB89A}',
'.sim-pati .p-te.new i{border-color:#E07A3F;box-shadow:0 0 0 4px #FBE6D8}',
'.sim-pati .p-te.next i{border-color:#DCCFC0;border-style:dashed}',
'.sim-pati .p-te .p-td{font-size:11.5px;font-weight:800;color:#7A665A;letter-spacing:.06em;text-transform:uppercase;display:flex;align-items:center;gap:6px}',
'.sim-pati .p-te .p-td em{font-style:normal;background:#FBE6D8;color:#B5551C;padding:1px 6px;border-radius:6px;letter-spacing:0;text-transform:none;font-size:11px}',
'.sim-pati .p-te.next .p-td em{background:#F3EADF;color:#5C4A3E}',
'.sim-pati .p-te .p-tt{font-size:15.5px;font-weight:800;margin-top:3px;line-height:1.2}',
'.sim-pati .p-te .p-ts{font-size:13px;color:#7A665A;margin-top:2px;font-weight:600;line-height:1.35}',
'.sim-pati .p-sum{display:flex;gap:8px;margin-bottom:14px}',
