/* training */
'.sim-pati .p-day{display:flex;gap:12px;padding:12px 0;border-bottom:1px solid #F0E6DA;align-items:flex-start;font-size:14px;line-height:1.4;font-weight:600}',
'.sim-pati .p-day:last-child{border:0}',
'.sim-pati .p-day b{flex:none;font-size:11.5px;font-weight:800;color:#24462E;background:#DDEBE0;border-radius:8px;padding:4px 8px;margin-top:1px;white-space:nowrap}',
/* sheet */
'.sim-pati .p-dim{position:absolute;inset:0;background:rgba(59,47,42,.38);z-index:11;opacity:0;transition:opacity .3s}',
'.sim-pati .p-dim.open{opacity:1}',
'.sim-pati .p-sheet{position:absolute;left:0;right:0;bottom:0;z-index:12;background:#FFFDF9;border-radius:28px 28px 0 0;padding:12px 18px 36px;transform:translateY(102%);transition:transform .32s cubic-bezier(.2,.8,.2,1);box-shadow:0 -10px 30px rgba(59,47,42,.18)}',
'.sim-pati .p-sheet.open{transform:none}',
'.sim-pati .p-grab{width:40px;height:5px;border-radius:3px;background:#DCCFC0;margin:0 auto 14px}',
'.sim-pati .p-vet{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid #F0E6DA}',
