'.sim-pati .p-vet .p-vs em{font-style:normal;color:#2F6A3F}',
'.sim-pati .p-vet .p-btn{margin-left:auto;background:#3B2F2A;color:#FBF6EF}',
'.sim-pati .p-in{width:100%;height:50px;border-radius:15px;border:1.5px solid #EADFD2;background:#FBF6EF;padding:0 14px;font-size:15px;font-weight:700;margin-top:8px}',
