'.sim-pati-cover .p-cv-card{position:absolute;right:18px;top:16px;width:130px;background:#FFFDF9;border:1px solid #F0E6DA;border-radius:18px;padding:11px 12px;box-shadow:0 10px 24px rgba(107,78,61,.13);transform:rotate(3deg);z-index:2}',
