'.sim-pati-cover .p-cv-card .p-cv-n{font-size:16px;line-height:1.05;margin-top:8px}',
'.sim-pati-cover .p-cv-card .p-cv-s{font-size:11px;color:#7A665A;font-weight:700;margin-top:3px;line-height:1.3}',
'.sim-pati-cover .p-cv-band{position:absolute;right:10px;bottom:12px;width:144px;background:#F7E3C4;color:#5A3A0E;border-radius:14px;padding:8px 10px;white-space:nowrap;font-size:11px;font-weight:800;line-height:1.3;transform:rotate(-3deg);z-index:3;box-shadow:0 8px 18px rgba(107,78,61,.12)}',
'.sim-pati-cover .p-cv-day{position:absolute;left:22px;bottom:18px;z-index:2;display:flex;align-items:center;gap:6px;font-size:11px;font-weight:800;color:#3B2F2A;white-space:nowrap}',
'.sim-pati-cover .p-cv-ring{width:22px;height:22px;border-radius:50%;background:conic-gradient(#8FB89A 60%,#EADFD2 0);position:relative;flex:none}',
'.sim-pati-cover .p-cv-ring:after{content:"";position:absolute;inset:5px;border-radius:50%;background:#FBF6EF}',
'.sim-pati-cover .p-cv-band small{display:block;font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:#8A5A12;margin-bottom:2px}',
'@media (prefers-reduced-motion:reduce){.sim-pati .p-pg,.sim-pati .p-te{animation:none}.sim-pati .p-pd i{animation:none;opacity:1;transform:none}.sim-pati .p-tr i{animation:none}.sim-pati .p-sheet,.sim-pati .p-dim,.sim-pati .p-bar i,.sim-pati .p-chip,.sim-pati .p-sw,.sim-pati .p-sw:after{transition:none}}'
