    function scanSources() {
      if (S.busy) return; S.busy = true; const n = $('[data-sn]'); n.textContent = 'Kaynaklar taranıyor…';
      later(() => {
        S.busy = false; n.textContent = 'Son tarama: şimdi';
        if (S.rep && S.watch && !S.alert) applyAlert();
        else toast('Kaynaklar tarandı · yeni değişiklik yok', S.rep && !S.watch ? 'Raporu izlemeye alın: değişiklikler uyarı olarak düşer (§4)' : 'İzlenen dosyalarda yeni taslak ya da karar yok');
      }, rm ? 0 : 1200);
    }
    function showTpl() { reset(); S.rep = true; renderRes(); renderRail(); scrollTo('[data-s=rep]', 14); revealAll(); }
