function rnd(seed){let s=seed;return()=>(s=s*16807%2147483647)/2147483647;}
function seal(sz){
let d='';
for(let i=0;i<=54;i++){const a=i/54*Math.PI*2,r=27+1.7*Math.sin(a*7)+1.1*Math.sin(a*12+1);d+=(i?'L':'M')+(30+r*Math.cos(a)).toFixed(1)+' '+(30+r*Math.sin(a)).toFixed(1);}
return`<svg class="seal" width="${sz}" height="${sz}" viewBox="0 0 60 60" aria-hidden="true"><path d="${d}Z" fill="#B8322A"/><circle cx="30" cy="30" r="20.5" fill="none" stroke="#8A231D" stroke-width="2"/><circle cx="30" cy="30" r="17.5" fill="#C63D31"/><text x="30" y="38.5" text-anchor="middle" font-family="Instrument Serif,Georgia,serif" font-size="27" font-style="italic" fill="#F8DDD2">c.</text></svg>`;
}
function qr(sz){
const r=rnd(142);let d='';
const fin=(x,y)=>{for(const[ox,oy]of[[0,0],[18,0],[0,18]]){const dx=x-ox,dy=y-oy;if(dx>=-1&&dx<=7&&dy>=-1&&dy<=7)return(dx<0||dy<0||dx>6||dy>6)?0:(dx%6===0||dy%6===0||(dx>1&&dx<5&&dy>1&&dy<5))?1:0;}return-1;};
for(let y=0;y<25;y++){let run=0;for(let x=0;x<=25;x++){let on=0;if(x<25){const f=fin(x,y);on=f<0?+(r()<.47):f;}if(on)run++;else if(run){d+=`M${x-run} ${y}h${run}v1h-${run}z`;run=0;}}}
return`<svg width="${sz}" height="${sz}" viewBox="-1 -1 27 27" shape-rendering="crispEdges" aria-hidden="true"><rect x="-1" y="-1" width="27" height="27" fill="#F7F3EA"/><path d="${d}" fill="#1D1B20"/></svg>`;
}
function wave(seed,col){
const r=rnd(seed);let o='';
for(let i=0;i<118;i++){const w=(i%29)>24?.08:.3+.7*Math.abs(Math.sin(i/3.7+seed)),h=Math.max(2,58*w*(.4+.6*r()));o+=`<rect x="${i*3}" y="${(32-h/2).toFixed(1)}" width="2" height="${h.toFixed(1)}" rx="1"/>`;}
return`<svg viewBox="0 0 354 64" preserveAspectRatio="none" fill="${col}" aria-hidden="true">${o}</svg>`;
}
