const tr=(l,s,sd,c)=>`<div class="tr"><div class="trh"><b>${l} · 15 sn</b><span>sürüm ${s}/20 · senaryo v2</span></div><div class="wv">${wave(sd,c)}<span class="rb">Filigran ✓</span></div></div>`;
