if (!t) return;
var to = t.getAttribute('data-to');
if (act === 'go' || act === 'tab') { st.screen = to || 'home'; st.warn = ''; if (raf) { cancelAnimationFrame(raf); raf = 0; } if (tw) { st.twDone = true; tw = null; } render(); }
