    [0, .5, 1].forEach(function (v) {
      g += '<line x1="' + L + '" x2="' + R + '" y1="' + cy(v).toFixed(1) + '" y2="' + cy(v).toFixed(1) + '" stroke="' + BD + '"/><line y1="' + T + '" y2="' + B + '" x1="' + cx(v).toFixed(1) + '" x2="' + cx(v).toFixed(1) + '" stroke="' + BD + '"/>';
      g += '<text x="' + (L - 6) + '" y="' + (cy(v) + 4).toFixed(1) + '" text-anchor="end">' + String(v).replace('.', ',') + '</text><text x="' + cx(v).toFixed(1) + '" y="' + (B + 16) + '" text-anchor="' + (v === 0 ? 'start' : v === 1 ? 'end' : 'middle') + '">' + String(v).replace('.', ',') + '</text>';
    });
    CAL.forEach(function (p, i) { d += (i ? 'L' : 'M') + cx(p[0]).toFixed(1) + ' ' + cy(p[1]).toFixed(1); dots += '<circle class="dt" cx="' + cx(p[0]).toFixed(1) + '" cy="' + cy(p[1]).toFixed(1) + '" r="3.5" fill="' + FG + '" stroke="' + BG + '" stroke-width="1.5"/>'; });
