      const root = document.createElement('div');
      root.className = 'sim-triage';
      root.setAttribute('lang', 'tr');
      root.innerHTML = `<div class="tg-cap"><i></i><span></span></div>
      <div class="tg-app">
        <header class="tg-hd"><div class="tg-brand">Demo triyaj <span>· Demo Talepleri</span></div><span class="tg-env"><i></i><span>demo verisi</span></span>
          <span class="tg-clock">${DAY} 24.09.2026 · 21:13</span><button data-refresh>Yenile</button><label><input type="checkbox" checked> 30 sn'de bir yenile</label></header>
        <main class="tg-main">
          <section class="tg-col tg-left"><div class="tg-colh">Gelen talepler <span data-count></span><em>aciliyete göre</em></div>
            <div class="tg-filters"><select data-verdict><option value="hepsi">Tüm kararlar</option><option value="gercek">Gerçek</option><option value="incele">İncele</option><option value="sahte">Sahte / spam</option></select><select data-sort><option value="aciliyet">Aciliyete göre</option><option value="yeni">En yeni önce</option></select><input type="search" data-q placeholder="İsim, e-posta, şirket ara"></div>
            <div class="tg-list"></div></section>
          <section class="tg-col"><div class="tg-panel tg-detail"></div></section>
          <section class="tg-col tg-right">
            <div class="tg-panel"><h3>Bu hafta <span>21–25.09 · Europe/Istanbul</span></h3><div class="tg-stats">
              <div class="tg-stat">Talep<b data-s="tot"></b></div><div class="tg-stat g">Gerçek<b data-s="g"></b></div><div class="tg-stat w">İncele<b data-s="i"></b></div><div class="tg-stat b">Sahte<b data-s="s"></b></div>
              <div class="tg-stat">Ort. atama<b>3,1<small>sn</small></b></div><div class="tg-stat">SLA aşımı<b>0</b></div></div></div>
            <div class="tg-panel tg-reps"><h3>Temsilci yükü <span>açık / atanan</span></h3><div data-reps></div></div>
            <div class="tg-panel"><h3>Diğer iş akışları <span>n8n · kod</span></h3><div class="tg-flows">${FLOWS.map((f, i) => `<button class="tg-flow" data-flow="${i}">${esc(f[0])}<small>${esc(f[1])}</small></button>`).join('')}</div><div class="tg-flowd">Sabit ücretli kurulum + aylık işletme; her adım denetim kaydına yazılır.</div></div>
          </section>
        </main></div>`;
      el.appendChild(root);
      const $ = s => root.querySelector(s);
      const cap = $('.tg-cap'), capT = $('.tg-cap span'), listEl = $('.tg-list'), detailEl = $('.tg-detail'), clockEl = $('.tg-clock'), repsEl = $('[data-reps]'), countEl = $('[data-count]'), flowdEl = $('.tg-flowd');
      const st = { leads: OLD.map(x => Object.assign({}, x)), stats: { tot: 21, g: 16, i: 4, s: 1 }, reps: REPS.map(r => Object.assign({}, r)), sel: null, repF: null, running: !reduced, done: false };
      NEW.forEach(x => { x._pend = false; x._new = false; x._in = false; x._s = false; x._r = false; });

      /* ---------- renderers ---------- */
