    const rowsHtml = COMPS.map((c, i) => `<tr class="pend" data-row="${i}"><td><span><b>${c.n}</b> · ${c.d}</span></td><td class="num"><span>${c.m ? '<b>' + fx(c.m) + '</b>' : 'ölçek primi'}</span></td><td><span><i class="role r${c.ri}">${c.r}</i></span></td><td><span><i class="k${c.k === 2 ? ' k2' : ''}">K${c.k}</i>${c.k === 1 ? 'Rekabet Kurulu' : 'Borsa kapanışı'}</span></td></tr>`).join('');
